@using sv_82a36196adfe47518e3605f58fedecd7.Models
@namespace sv_82a36196adfe47518e3605f58fedecd7.Components.Pages.Apply

<div class="step-form">
    <h3>References</h3>
    <p class="form-hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < references.Count; i++)
    {
        var index = i;
        <ReferenceForm Ref="references[index]"
                       Index="index"
                       ShowRemove="references.Count > 2"
                       OnRefChanged="e => UpdateReference(index, e)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (references.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="validation-summary">@validationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<Reference> references = new();
    private string? validationError;

    protected override void OnParametersSet()
    {
        if (references.Count == 0)
        {
            references = References.Count > 0
                ? References.ToList()
                : new List<Reference> { new("", "", "", ""), new("", "", "", "") };
        }
    }

    private void UpdateReference(int index, Reference updated)
    {
        references[index] = updated;
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new Reference("", "", "", ""));
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        validationError = null;
        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
