@page "/apply"
@using sv_82a36196adfe47518e3605f58fedecd7.Models
@using sv_82a36196adfe47518e3605f58fedecd7.Components.Pages.Apply
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepSelected="GoToStep" />

    @if (submittedId.HasValue)
    {
        <div class="submission-confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received. Your confirmation number is:</p>
            <div class="application-id">@submittedId.Value</div>
            <p>Please save this number for your records.</p>
        </div>
    }
    else
    {
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;
            case 1:
                <WorkHistoryStep Entries="workEntries"
                                 OnNext="HandleWorkNext"
                                 OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep References="references"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep Personal="@GetPersonalInfo()"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="@coverLetter"
                            IsSubmitting="isSubmitting"
                            OnSubmit="HandleSubmit"
                            OnBack="GoBack"
                            OnEditSection="GoToStep" />
                break;
        }
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();

    // Step 1 data
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 data
    private List<WorkEntry> workEntries = new();

    // Step 3 data
    private List<Reference> references = new();

    // Step 4 data
    private string coverLetter = "";

    // Submission state
    private bool isSubmitting;
    private int? submittedId;

    private PersonalInfo GetPersonalInfo() => new(fullName, email, phone, address);

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntry> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        try
        {
            var application = new JobApplication(
                GetPersonalInfo(),
                new WorkHistory(workEntries),
                references,
                coverLetter
            );
            submittedId = await ApplicationService.SubmitApplicationAsync(application);
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

.application-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
